interface Message { flag?: boolean; }
function diag(flag?: boolean) { return { flag }; }
const value = diag() as Message;
console.log("ok");

let x = 0;
const value = (x++, x);
console.log(`${value}`);

const Debug = { fail: (message: string): never => { throw new Error(message); } };
function read(values: readonly number[]): number { return values[0] ?? Debug.fail("missing"); }
console.log(`${read([1])}`);
